---- history line
/* The card rests as its <summary>; the forensic detail stays mounted in the
   sibling block that the disclosure reveals. */
.history-summary {
  display: flex;
  flex-direction: column;
  gap: 4px;
  list-style: none;
  cursor: pointer;
}
.history-summary::-webkit-details-marker {
  display: none;
}
.history-summary-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.history-title {
  display: flex;
  align-items: baseline;
  gap: 4px;
  min-width: 0;
}
.history-time {
  flex: 0 0 auto;
  margin-left: auto;
  color: var(--text-secondary);
  font: var(--font-metadata);
  white-space: nowrap;
}
/* Figma sets the resting lines at 13px, which is between Label and Body and
   has no token; Label is the nearest role the token file emits. */
.history-line {
  min-width: 0;
  color: var(--text-secondary);
  font: var(--font-label);
}
/* A build's short output hash: an ID, which is what the code face is now
   reserved for. */
.history-line code {
  color: var(--text-secondary);
  font: var(--font-code);
  overflow-wrap: anywhere;
  user-select: text;

